contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We'll drive deposit of underlyingBorrowToken into the protocol.
    // params:
    // - token: address of underlying borrow token (must match c.data().underlyingBorrowToken)
    // - amount: amount to deposit
    // - to: recipient account in the protocol
    function run(address token, uint256 amount, address to) public payable {
        require(amount != 0);
        // Observe data view before the operation
        (uint256 nextDebtId, uint256 nextCreditId) = c.getPositionsCount();
        // read borrowAToken and debtToken total supplies via data()
        (/*nextDebt*/, /*nextCredit*/, , , , , , , ,) = c.data();

        // We can only observe borrowAToken.totalSupply() and debtToken.totalSupply() through data().
        // But data().borrowAToken is a NonTransferrableScaledToken with public totalSupply and liquidityIndex accessible via its getters.
        // Fetch borrowAToken and debtToken addresses via data() and then call totals.
        // The SizeView.data() returns DataView including borrowAToken and debtToken as contract instances.
        DataView memory dv = c.data();
        uint256 borrowSupplyBefore = dv.borrowAToken.totalSupply();
        uint256 debtSupplyBefore = dv.debtToken.totalSupply();

        // The test will attempt to deposit the underlying borrow token into the protocol by calling deposit
        // Build DepositParams ABI: (address token, uint256 amount, address to)
        // This call must come from this contract (msg.sender = this test contract)
        // Ensure the test contract has enough Ether if token is WETH: we won't send ETH here, as depositing ERC20

        // Execute the deposit. It might revert due to invalid token or approvals; catch revert.
        bool reverted;
        try c.deposit{value: 0}(DepositParams({token: token, amount: amount, to: to})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read supplies after (if revert occurred supplies unchanged)
        DataView memory dvAfter = c.data();
        uint256 borrowSupplyAfter = dvAfter.borrowAToken.totalSupply();
        uint256 debtSupplyAfter = dvAfter.debtToken.totalSupply();

        // General rule to assert:
        // If deposit succeeded (not reverted) then borrowAToken.totalSupply() did not decrease, and debtToken.totalSupply() did not decrease.
        // Additionally, borrowSupplyAfter >= borrowSupplyBefore (monotonic non-decreasing), and debtSupplyAfter >= debtSupplyBefore (non-decreasing).
        assert(
            reverted
                || (borrowSupplyAfter >= borrowSupplyBefore && debtSupplyAfter >= debtSupplyBefore)
        );
    }

    // Minimal types and helpers to match ABI expected by calls and reads.
    // We declare these to satisfy the compiler for struct usage; they mirror definitions in the main file.
    struct DataView { uint256 nextDebtPositionId; uint256 nextCreditPositionId; IERC20Metadata underlyingCollateralToken; IERC20Metadata underlyingBorrowToken; IPool variablePool; NonTransferrableToken collateralToken; NonTransferrableScaledToken borrowAToken; NonTransferrableToken debtToken; }
    struct DepositParams { address token; uint256 amount; address to; }

    // We need to import the minimal interfaces used above as types. Declare them as empty so compilation succeeds referencing from this test file only.
    // These are references to already-defined types in the compilation unit; redeclaring as interfaces with same names causes conflicts, so instead use type aliases by referencing existing contract C's public types indirectly is not possible.
    // However, referencing these names in struct fields is allowed because they exist in the compilation unit.

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test deposit: if it succeeds, borrowAToken.totalSupply() and debtToken.totalSupply()
    // must be >= their previous values; if it reverts they remain equal to before.
    // params: token (address), amount (uint256), to (address)
    function run(address token, uint256 amount, address to) public payable {
        require(to != address(0));

        // Read supplies before via public data() view
        ISize.DataView memory dvBefore = c.data();
        uint256 borrowSupplyBefore = dvBefore.borrowAToken.totalSupply();
        uint256 debtSupplyBefore = dvBefore.debtToken.totalSupply();

        // Perform deposit and catch revert
        bool reverted;
        // Build DepositParams ABI in calldata by encoding (address,uint256,address)
        bytes memory encoded = abi.encodeWithSignature("deposit((address,uint256,address))", (token, amount, to));
        // However C.deposit expects DepositParams calldata; the above signature with a tuple is not standard for external encoding.
        // To call properly, use the concrete selector for deposit: function deposit(DepositParams calldata) external payable;
        // DepositParams layout is (address,uint256,address) so selector is keccak("deposit((address,uint256,address))")[0:4]
        // We already encoded that; try delegate via low-level call on c.
        // But must send as call to c; capture revert via try/catch by calling the high-level function instead.
        // High-level call using c.deposit is allowed; construct the DepositParams struct inline.
        // Note: solidity allows calling c.deposit{value:...}(DepositParams({token:..., amount:..., to:...})).

        // Attempt high-level call and catch revert
        try c.deposit{value: msg.value}(ISize.DepositParams({token: token, amount: amount, to: to})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read supplies after
        ISize.DataView memory dvAfter = c.data();
        uint256 borrowSupplyAfter = dvAfter.borrowAToken.totalSupply();
        uint256 debtSupplyAfter = dvAfter.debtToken.totalSupply();

        // Assert the invariant:
        // - If deposit reverted: supplies unchanged
        // - If deposit succeeded: supplies did not decrease
        assert(
            reverted
                ? (borrowSupplyAfter == borrowSupplyBefore && debtSupplyAfter == debtSupplyBefore)
                : (borrowSupplyAfter >= borrowSupplyBefore && debtSupplyAfter >= debtSupplyBefore)
        );
    }

    // receive to accept ETH if test caller funds this contract prior to calling run
    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // Test that deposit keeps borrowAToken.totalSupply() and debtToken.totalSupply() non-decreasing on success,
    // and unchanged on revert.
    // params: token, amount, to, ethValue (for payable deposits when token==weth)
    function run(address token, uint256 amount, address to, uint256 ethValue) public payable {
        // basic preconditions for meaningful call
        require(to != address(0));
        require(address(this).balance >= ethValue);

        // Read supplies before via c.data() view (DataView has borrowAToken and debtToken)
        (uint256 beforeBorrowSupply, uint256 beforeDebtSupply) = _readSupplies();

        // Attempt the deposit and catch revert
        bool reverted;
        // Build DepositParams struct inline and call high-level function
        ISize.DepositParams memory params = ISize.DepositParams({token: token, amount: amount, to: to});
        // If ethValue > 0, send it. Ensure we use the provided ethValue and not msg.value.
        if (ethValue > 0) {
            // call with value
            try c.deposit{value: ethValue}(params) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.deposit(params) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read supplies after
        (uint256 afterBorrowSupply, uint256 afterDebtSupply) = _readSupplies();

        // Assert invariant: if reverted -> supplies equal; else supplies non-decreasing
        assert(
            reverted
                ? (afterBorrowSupply == beforeBorrowSupply && afterDebtSupply == beforeDebtSupply)
                : (afterBorrowSupply >= beforeBorrowSupply && afterDebtSupply >= beforeDebtSupply)
        );
    }

    // helper to read supplies via c.data() view; allowed observation of c only via its public surface
    function _readSupplies() internal view returns (uint256 borrowSupply, uint256 debtSupply) {
        ISize.DataView memory dv = c.data();
        borrowSupply = dv.borrowAToken.totalSupply();
        debtSupply = dv.debtToken.totalSupply();
    }

    // Allow receiving ETH so run can use ethValue funded to this contract beforehand
    receive() external payable {}
}

