contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We take as parameters an array of calldata payloads and send them via multicall.
    // Also allow sending some Ether along to exercise deposit paths.
    function run(bytes[] calldata data, uint256 ethAmount) public payable {
        // ensure this contract has enough balance to forward ethAmount to multicall
        require(address(this).balance >= ethAmount, "insufficient balance for test");

        // Read supplies before
        (uint256 beforeDebtCount, uint256 beforeCreditCount) = c.getPositionsCount();
        // Observe borrowAToken and debtToken totalSupply via data view: data() returns DataView
        ISize.DataView memory dvBefore = c.data();
        uint256 borrowATokenSupplyBefore = dvBefore.borrowAToken.totalSupply();
        uint256 debtTokenSupplyBefore = dvBefore.debtToken.totalSupply();

        // Attempt multicall; capture whether it reverts
        bool reverted;
        bytes[] memory results;
        try c.multicall{value: ethAmount}(data) returns (bytes[] memory r) {
            reverted = false;
            results = r;
        } catch {
            reverted = true;
        }

        // Read supplies after (if multicall reverted, state shouldn't have changed)
        ISize.DataView memory dvAfter = c.data();
        uint256 borrowATokenSupplyAfter = dvAfter.borrowAToken.totalSupply();
        uint256 debtTokenSupplyAfter = dvAfter.debtToken.totalSupply();

        // The general invariant enforced by Multicall: if borrowATokenSupplyAfter > state.riskConfig.borrowATokenCap()
        // then the increase in borrowATokenSupply (after - before) must be <= decrease in debtTokenSupply (before - after).
        // We cannot read riskConfig directly, but we can assert the inequality that Multicall enforces in execute: whenever
        // borrowATokenSupplyAfter > borrowATokenSupplyBefore (i.e. supply increased) the relation holds.
        // Formally: borrowIncrease <= debtDecrease OR borrowATokenSupplyAfter <= borrowATokenSupplyBefore OR multicall reverted

        // compute increase/decrease without underflow: use comparisons
        bool borrowIncreased = borrowATokenSupplyAfter > borrowATokenSupplyBefore;
        bool debtDecreased = debtTokenSupplyAfter < debtTokenSupplyBefore;

        uint256 borrowIncrease = borrowIncreased ? borrowATokenSupplyAfter - borrowATokenSupplyBefore : 0;
        uint256 debtDecrease = debtDecreased ? debtTokenSupplyBefore - debtTokenSupplyAfter : 0;

        // Assert the invariant: if multicall succeeded and borrow increased and borrow supply after is above before, then borrowIncrease <= debtDecrease
        assert(reverted || !borrowIncreased || borrowIncrease <= debtDecrease);
    }

    // Allow contract to receive ETH for testing
    receive() external payable {}
}

