        ISize.DataView memory dvBefore = c.data();
        uint256 borrowATokenSupplyBefore = dvBefore.borrowAToken.totalSupply();
        uint256 debtTokenSupplyBefore = dvBefore.debtToken.totalSupply();

        // Call multicall and record whether it reverted
        bool reverted;
        try c.multicall{value: ethAmount}(data) returns (bytes[] memory) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read supplies after
        ISize.DataView memory dvAfter = c.data();
        uint256 borrowATokenSupplyAfter = dvAfter.borrowAToken.totalSupply();
        uint256 debtTokenSupplyAfter = dvAfter.debtToken.totalSupply();

        // Compute increase/decrease without underflow
        bool borrowIncreased = borrowATokenSupplyAfter > borrowATokenSupplyBefore;
        bool debtDecreased = debtTokenSupplyAfter < debtTokenSupplyBefore;

        uint256 borrowIncrease = borrowIncreased ? borrowATokenSupplyAfter - borrowATokenSupplyBefore : 0;
        uint256 debtDecrease = debtDecreased ? debtTokenSupplyBefore - debtTokenSupplyAfter : 0;

        // General rule: if multicall succeeded, then any increase in borrowAToken supply must be <= decrease in debtToken supply.
