contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: token must be an address; if token == underlyingCollateralToken of c, deposit should mint 1:1 collateralToken
    // amount must be >0 and `to` arbitrary
    function run(address token, uint256 amount, address to) public payable {
        // we will only test the deposit flow for underlyingCollateralToken
        // require we have enough ETH if caller intends to send msg.value for WETH deposits
        // but here we only interact with public view functions and call deposit via c.deposit
        // Precondition: amount > 0 to avoid trivial rejected deposits by protocol
        require(amount > 0);

        // Read data view to obtain the underlyingCollateralToken address
        // data() is external view and returns a DataView struct
        ISizeView.DataView memory dv = c.data();
        address underlyingCollateral = address(dv.underlyingCollateralToken);

        // Only proceed with the case where provided token equals the underlyingCollateralToken
        // If not equal we still execute but assert will be vacuously about equality
        // Prepare DepositParams ABI encoding
        bytes memory depositCalldata = abi.encodeWithSelector(
            c.deposit.selector,
            // DepositParams { token, amount, to }
            // The function is external, so we pass a tuple matching the struct
            // Solidity ABI encodes the struct inline as (address,uint256,address)
            (token, amount, to)
        );

        // Capture recipient collateral token balance before
        uint256 before;
        // Only readable via SizeView.getUserView or via collateralToken.balanceOf through data().collateralToken
        // Use getUserView to read balances
        ISizeView.UserView memory uvBefore = c.getUserView(to);
        before = uvBefore.collateralTokenBalance;

        bool reverted = false;
        // Call deposit on c. send no ETH from this test (unless token==WETH and msg.value intended, but we avoid sending ETH)
        try c.deposit{value: 0}(ISize.DepositParams({token: token, amount: amount, to: to})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balance after
        ISizeView.UserView memory uvAfter = c.getUserView(to);
        uint256 after = uvAfter.collateralTokenBalance;

        // If the token passed equals the protocol's underlyingCollateralToken and deposit did not revert,
        // then the recipient's collateral token balance must have increased by exactly `amount` (1:1 mint).
        // General rule: token == underlyingCollateral && !reverted => after == before + amount
        assert(!(token == underlyingCollateral && !reverted) || after == before + amount);
    }

    // receive to accept ETH if needed (not used here)
    receive() external payable {}
}

