    function run(address token, uint256 amount, address to) public payable {
        // amount must be non-zero to pass deposit validation and avoid trivial no-op
        require(amount > 0);
        // Read protocol data view to obtain underlyingCollateralToken and collateralToken via public view
        (uint256 nextDebtPositionId, uint256 nextCreditPositionId) = c.getPositionsCount();
        // Use c.data() via the ISizeView data() signature: returns a struct DataView but we cannot name its type here
        // So call c.data() and then extract underlyingCollateralToken by calling getUserView on address 0 to avoid using the struct type.
        // Instead, obtain underlyingCollateralToken address by reading getSwapFee with a dummy tenor and catching revert if needed.
        // Simpler: call c.data() and rely on tuple assignment of the known first two returns of getPositionsCount above to ensure previous line compiles.

        // Read recipient collateral token balance before via public getter getUserView
        // getUserView returns a struct; we can call and read its returned collateralTokenBalance by assigning to a tuple via ABI encoding trick
        // Solidity can't destructure returned struct easily without type; instead call c.getUserView(to) and rely on ABI decoding via low-level call
        bytes memory viewCallData = abi.encodeWithSelector(c.getUserView.selector, to);
        (bool okBefore, bytes memory retBefore) = address(c).staticcall(viewCallData);
        // If the view failed, set beforeBalance = 0 (this shouldn't happen on a fresh contract)
        uint256 beforeBalance = 0;
        if (okBefore && retBefore.length >= 32 * 5) {
            // UserView layout: User user; address account; uint256 collateralTokenBalance; uint256 borrowATokenBalance; uint256 debtBalance;
            // The ABI encoding places the collateralTokenBalance at slot 3 (after dynamic user struct and account). To be safe, parse by decoding as the full tuple type via known types.
            // Decode as (tuple, address, uint256, uint256, uint256)
            (/* user */, /* account */, beforeBalance, /* borrowATokenBalance */, /* debtBalance */) = abi.decode(
                retBefore, (bytes, address, uint256, uint256, uint256)
            );
        }

        bool reverted;
        // perform deposit call; we call without sending ETH here
        try c.deposit{value: 0}(ISize.DepositParams({token: token, amount: amount, to: to})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read recipient collateral balance after
        (bool okAfter, bytes memory retAfter) = address(c).staticcall(viewCallData);
        uint256 afterBalance = 0;
        if (okAfter && retAfter.length >= 32 * 5) {
            (/* user */, /* account */, afterBalance, /* borrowATokenBalance */, /* debtBalance */) = abi.decode(
                retAfter, (bytes, address, uint256, uint256, uint256)
            );
        }

        // Also obtain underlyingCollateralToken address to check the token parameter
        bytes memory dataViewCall = abi.encodeWithSelector(c.data.selector);
        (bool okData, bytes memory retData) = address(c).staticcall(dataViewCall);
        address underlyingCollateral = address(0);
        if (okData && retData.length >= 32 * 7) {
            // DataView struct returned: (uint256 nextDebtPositionId, uint256 nextCreditPositionId, IERC20Metadata underlyingCollateralToken, IERC20Metadata underlyingBorrowToken, IPool variablePool, NonTransferrableToken collateralToken, NonTransferrableScaledToken borrowAToken, NonTransferrableToken debtToken)
            // We decode the first two uint256 and then the next items as addresses. The third item (underlyingCollateralToken) is at position 3.
            (uint256 _n1, uint256 _n2, address underlyingCollateralAddr) = abi.decode(
                // decode only the first three items; safe because abi.decode can decode subset if types match layout
                retData, (uint256, uint256, address)
            );
            underlyingCollateral = underlyingCollateralAddr;
        }

        // If token equals underlyingCollateral and the deposit did not revert, the recipient's collateral token balance must increase exactly by amount
        assert(!(token == underlyingCollateral && !reverted) || afterBalance == beforeBalance + amount);
    }

    receive() external payable {}
}

