    // params:
    // token: address of token to deposit (must be either underlyingCollateralToken or underlyingBorrowToken)
    // amount: amount to deposit
    // to: recipient address
    // useEth: if true, send Ether with the call (only valid when token == weth)
    function run(address token, uint256 amount, address to, bool useEth) public payable {
        // we will call deposit on c. If useEth, ensure this contract has enough balance to forward
        if (useEth) {
            require(address(this).balance >= amount, "not enough balance to forward eth");
        }

        // read c's data view to obtain underlyingCollateralToken address
        // Using public view get via ISizeView functions implemented in C
        // c.data() returns DataView with underlyingCollateralToken and underlyingBorrowToken
        (uint256 nextDebtPositionId, uint256 nextCreditPositionId, IERC20Metadata underlyingCollateralToken,
            IERC20Metadata underlyingBorrowToken, , , , ) = c.data();

        // Only proceed with tokens that the protocol supports
        require(token == address(underlyingCollateralToken) || token == address(underlyingBorrowToken), "unsupported token");

        // read recipient collateral token balance before (only observable via getUserView)
        // getUserView returns collateralTokenBalance
        ISizeView.UserView memory beforeView = c.getUserView(to);
        uint256 beforeCollateralBalance = beforeView.collateralTokenBalance;

        // record contract balances
        uint256 beforeCBalance = address(c).balance;

        // Prepare calldata for deposit
        ISize.DepositParams memory params = ISize.DepositParams({token: token, amount: amount, to: to});

        bool reverted = false;
        if (useEth) {
            // call with value
            try c.deposit{value: amount}(params) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.deposit(params) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Read after-values
        ISizeView.UserView memory afterView = c.getUserView(to);
        uint256 afterCollateralBalance = afterView.collateralTokenBalance;
        uint256 afterCBalance = address(c).balance;

        // General rule to assert:
        // If the deposit call succeeded and token == underlyingCollateralToken, then the recipient's collateral token balance increased by at most amount.
        // Also, if the call succeeded and useEth==true, then c's ETH balance increased by amount.
        // If the call reverted, we don't require balance changes. Express as a single assert.
        if (!reverted) {
            if (token == address(underlyingCollateralToken)) {
                // collateral token minted 1:1 when depositing underlying collateral token
                // afterCollateralBalance - beforeCollateralBalance <= amount
                assert(afterCollateralBalance >= beforeCollateralBalance && afterCollateralBalance - beforeCollateralBalance <= amount);
            } else {
                // If depositing borrow token, collateral balance should be unchanged
                assert(afterCollateralBalance == beforeCollateralBalance);
            }

            if (useEth && token == address(underlyingBorrowToken) == false) {
                // Only when Ether path used (msg.value) and token is weth, deposit uses msg.value path -> c.balance increases by amount
                // But we can't detect weth address equality easily here; conservative: if useEth then c.balance increased by amount
                assert(afterCBalance == beforeCBalance + amount);
            } else if (useEth) {
                // fallback: if useEth true we still expect c balance to increase by amount
                assert(afterCBalance == beforeCBalance + amount);
            } else {
                // if not using eth, c balance should be unchanged
                assert(afterCBalance == beforeCBalance);
            }
        } else {
            // If reverted, no guarantees — but assert that either collateral balance didn't increase beyond amount
            // ensure no inexplicable huge mint: afterCollateralBalance - beforeCollateralBalance <= amount
            // use safe check without underflow
            if (afterCollateralBalance >= beforeCollateralBalance) {
                assert(afterCollateralBalance - beforeCollateralBalance <= amount);
            } else {
                // if decreased, still allow (burn) — accept
                assert(true);
            }
        }
    }

    receive() external payable {}
}

