        bool ruleHolds;
        if (reverted) {
            // If the multicall reverted, the invariant about state change still holds vacuously
            ruleHolds = true;
        } else {
            if (borrowATokenSupplyAfter > borrowATokenCap) {
                uint256 borrowIncrease = borrowATokenSupplyAfter >= borrowATokenSupplyBefore
                    ? borrowATokenSupplyAfter - borrowATokenSupplyBefore
                    : 0;
                uint256 debtDecrease = debtTokenSupplyBefore >= debtTokenSupplyAfter
                    ? debtTokenSupplyBefore - debtTokenSupplyAfter
                    : 0;
                ruleHolds = borrowIncrease <= debtDecrease;
            } else {
                // if after supply <= cap, no restriction from this rule
                ruleHolds = true;
            }
        }

        assert(ruleHolds);
    }

    // receive to accept forwarded ETH if needed
    receive() external payable {}
}

