            address afterUnderlyingBorrowToken, address afterVariablePool, address afterCollateralToken,
            address afterBorrowAToken, address afterDebtToken) = c.data();

        uint256 borrowATokenSupplyAfter = _totalSupplyOf(afterBorrowAToken);
        uint256 debtTokenSupplyAfter = _totalSupplyOf(afterDebtToken);

