    function _totalSupplyOf(address tokenAddr) internal view returns (uint256 supply) {
        // bytes4(keccak256("totalSupply()")) == 0x18160ddd
        (bool ok, bytes memory ret) = tokenAddr.staticcall(abi.encodeWithSelector(0x18160ddd));
        if (!ok || ret.length < 32) return 0;
        assembly { supply := mload(add(ret, 32)) }
    }

    receive() external payable {}
}

