    // Note: multicall will execute delegatecalls to c's functions; we call c.multicall once with encoded array.
    function run(bytes[] calldata calls, uint256[] calldata sendAmounts) public payable {
        require(calls.length == sendAmounts.length, "len");

        // read before-values (public view)
        uint256 beforeBorrowATokenSupply = c.data().borrowAToken.totalSupply();
        uint256 beforeDebtTokenSupply = c.data().debtToken.totalSupply();

