        // we sum requested sendAmounts and send that as value to c.multicall.
        uint256 totalValue = 0;
        for (uint256 i = 0; i < sendAmounts.length; i++) {
            totalValue += sendAmounts[i];
        }

        // ensure this contract has enough balance to forward value
        require(address(this).balance >= totalValue, "insufficient balance to forward");

        bool reverted;
        bytes[] memory results;
        // call multicall with the provided calls, forwarding totalValue wei
        try c.multicall{value: totalValue}(calls) returns (bytes[] memory r) {
