        // We assert a relation combining both cases:
        // If reverted: supplies unchanged. If not reverted: borrow supply did not decrease.
        assert(
            (reverted && afterBorrowATokenSupply == beforeBorrowATokenSupply && afterDebtTokenSupply == beforeDebtTokenSupply)
            || (!reverted && afterBorrowATokenSupply >= beforeBorrowATokenSupply)
        );
    }

