        // Use public data() to fetch borrowAToken address and then call its balanceOf via SizeView getUserView
        C.DataView memory dv = c.data();
        // Note: dv.borrowAToken is a NonTransferrableScaledToken with public balanceOf view returning unscaled balance
        uint256 beforeBalance = dv.borrowAToken.balanceOf(address(this));

        bool depositReverted = false;
        bool withdrawReverted = false;

        // Attempt deposit: if tokenIsWethFlag != 0 we'll send Ether to deposit as WETH path
        if (tokenIsWethFlag != address(0)) {
            // ensure we have enough balance to send
            require(address(this).balance >= amount);
            try c.deposit{value: amount}(C.DepositParams({token: address(dv.underlyingBorrowToken), amount: amount, to: address(this)})) {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
