            // If not using ETH path, still try deposit without value (may revert due to lack of ERC20 approvals)
            try c.deposit(C.DepositParams({token: address(dv.underlyingBorrowToken), amount: amount, to: address(this)})) {
                depositReverted = false;
            } catch {
                depositReverted = true;
            }
        }

