        C.DataView memory dv2 = c.data();
        uint256 afterBalance = dv2.borrowAToken.balanceOf(address(this));

        // If either operation reverted, we cannot reason about balances; in that case assert that at least one reverted.
        // Otherwise, the borrowAToken balance after must be >= before (no unexpected loss).
        assert(
            depositReverted || withdrawReverted || afterBalance >= beforeBalance
        );
    }

