            reverted = false;
            results = r;
        } catch {
            reverted = true;
        }

        uint256 borrowAfter = borrowAToken.totalSupply();
        uint256 debtAfter = debtToken.totalSupply();

        // The protocol enforces (when multicall completes) that if borrowATokenSupply increased above cap,
        // then borrowIncrease <= debtDecrease. We assert a general invariant consistent with that:
        // borrowAfter - borrowBefore <= debtBefore - debtAfter  OR multicall reverted.
        // To avoid underflow in uint, compare via cross checks.

        bool holds;
