                // word 2: ret[64:96] -> underlyingCollateralToken
                // word 3: ret[96:128] -> underlyingBorrowToken
                // word 4: ret[128:160] -> variablePool
                // word 5: ret[160:192] -> collateralToken
                // Note: addresses are right-aligned in 32 bytes; we cast from uint256 to address.
                uint256 w2;
                uint256 w5;
                assembly {
                    w2 := mload(add(ret, 96))
                    w5 := mload(add(ret, 192))
                }
                underlyingCollateralToken = address(uint160(w2));
                collateralTokenAddr = address(uint160(w5));
            } else {
                underlyingCollateralToken = address(0);
                collateralTokenAddr = address(0);
            }
        }

        // Try calling deposit; capture whether it reverted.
        bool didRevert;
        DepositParams memory p = DepositParams({ token: token, amount: amount, to: to });
        // Must perform top-level state-changing call on c
        try c.deposit{value: 0}(p) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        // Observe collateral token balanceOf(to) if we have the collateral token address
        uint256 observedCollateralBalance = 0;
        if (collateralTokenAddr != address(0)) {
            (bool ok2, bytes memory out) = collateralTokenAddr.staticcall(
                abi.encodeWithSignature("balanceOf(address)", to)
            );
            if (ok2 && out.length >= 32) {
                observedCollateralBalance = abi.decode(out, (uint256));
            } else {
                // If we can't read balance, set to 0 which will make the assertion conservative
                observedCollateralBalance = 0;
            }
        }

        // If the token passed equals the protocol's underlyingCollateralToken (and we successfully fetched that address),
        // then either the deposit reverted, or the recipient's collateralToken balance must be >= amount.
        bool tokenIsCollateral = (underlyingCollateralToken != address(0) && token == underlyingCollateralToken);

        assert(!tokenIsCollateral || didRevert || observedCollateralBalance >= amount);
    }

    // Minimal typed helper structs to build the deposit params for the external call
    struct YieldCurve { uint256[] tenors; int256[] aprs; uint256[] marketRateMultipliers; }
    struct LoanOffer { uint256 maxDueDate; YieldCurve curveRelativeTime; }
    struct BorrowOffer { YieldCurve curveRelativeTime; }
    struct User { LoanOffer loanOffer; BorrowOffer borrowOffer; uint256 openingLimitBorrowCR; bool allCreditPositionsForSaleDisabled; }

    struct DepositParams { address token; uint256 amount; address to; }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test: for any inputs, if deposit succeeds when using the protocol's underlyingCollateralToken,
    // then the recipient's collateralToken.balanceOf(to) >= amount.
    // The function is payable in case the protocol expects Ether for WETH deposits; we do not rely on msg.value.
    function run(address token, uint256 amount, address to) public payable {
        // meaningful inputs for the scenario we care about
        require(amount > 0);
        require(to != address(0));

        // Call the public view c.data() to obtain the protocol's underlyingCollateralToken and collateralToken addresses.
        // data() returns a tuple (DataView). We perform a staticcall and decode the returned ABI-encoded tuple.
        address underlyingCollateralToken = address(0);
        address collateralTokenAddr = address(0);
        {
            (bool ok, bytes memory ret) = address(c).staticcall(abi.encodeWithSignature("data()"));
            if (ok && ret.length >= 32 * 7) {
                // DataView returned by SizeView.data():
                // (uint256 nextDebtPositionId, uint256 nextCreditPositionId, address underlyingCollateralToken,
                //  address underlyingBorrowToken, address variablePool, address collateralToken, address borrowAToken, address debtToken?)
                // Extract word 2 and word 5 (zero-based) from returned tuple.
                uint256 w2;
                uint256 w5;
                assembly {
                    w2 := mload(add(ret, 96))
                    w5 := mload(add(ret, 192))
                }
                underlyingCollateralToken = address(uint160(w2));
                collateralTokenAddr = address(uint160(w5));
            }
        }

        // Prepare ABI-encoded DepositParams for external call: struct DepositParams { address token; uint256 amount; address to; }
        bytes memory params = abi.encode(token, amount, to);

        // Try calling deposit; capture whether it reverted.
        bool didRevert;
        {
            // top-level call that may change c's state
            try c.deposit{value: 0}(abi.decode(params, (address)), abi.decode(params, (uint256)), abi.decode(params, (address))) {
                // The above does not match c.deposit signature; c.deposit expects a single struct. Instead call via low-level.
                didRevert = false; // placeholder, will be overwritten by next block
            } catch {
                // ignore; we'll do a low-level call below
                didRevert = true;
            }
        }

        // The above try/catch can't call the struct-typed deposit directly due to mismatch; perform a low-level call to invoke deposit with the struct ABI.
        // Build the calldata for deposit((address,uint256,address)) where the param is a tuple matching DepositParams struct.
        bytes memory calldataPayload = abi.encodeWithSignature("deposit((address,uint256,address))", (token, amount, to));
        // Execute low-level call and detect revert without nesting state-changing call inside conditional.
        bool success;
        bytes memory resp;
        (success, resp) = address(c).call{value: 0}(calldataPayload);
        didRevert = !success;

        // Observe collateral token balanceOf(to) if we have the collateral token address
        uint256 observedCollateralBalance = 0;
        if (collateralTokenAddr != address(0)) {
            (bool ok2, bytes memory out) = collateralTokenAddr.staticcall(
                abi.encodeWithSignature("balanceOf(address)", to)
            );
            if (ok2 && out.length >= 32) {
                observedCollateralBalance = abi.decode(out, (uint256));
            } else {
                observedCollateralBalance = 0;
            }
        }

        // If the token passed equals the protocol's underlyingCollateralToken (and we successfully fetched that address),
        // then either the deposit reverted, or the recipient's collateralToken balance must be >= amount.
        bool tokenIsCollateral = (underlyingCollateralToken != address(0) && token == underlyingCollateralToken);

        assert(!tokenIsCollateral || didRevert || observedCollateralBalance >= amount);
    }

    // receive to accept Ether if needed by the environment
    receive() external payable {}

    // Fallback not used but present
    fallback() external payable {}
}
